    h, w = len(grid), len(grid[0])
    # Find the solid divider whose removal leaves equal-sized panels.
    sep = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r == h - 1 - r:
            sep = ('h', r)
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - 1 - c:
                sep = ('v', c)
                break
    if sep is None:
        raise ValueError('No centered solid divider found')
    orient, k = sep
    if orient == 'h':
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    from collections import Counter
    ca = Counter(x for row in a for x in row)
    cb = Counter(x for row in b for x in row)
    common = set(ca) & set(cb)
    color = min(common, key=lambda x: ca[x] + cb[x])
    # A solitary shared marker in one panel selects a solid-color output.
    solid = min(ca[color], cb[color]) == 1
    if orient == 'h':
        return [[color if solid else (3 if a[r][c] == color and b[r][c] == color else color)
                 for c in range(len(a[0]))] for r in range(len(a))]
    return [[color if solid else (3 if a[r][c] == color and b[r][c] == color else color)
             for c in range(len(a[0]))] for r in range(h)]

